UPDATE tb_sales_delivery_dt
SET revenue_closed_at = CURRENT_TIMESTAMP,
    revenue_closed_by = #{userId, jdbcType=VARCHAR}
WHERE tenant_id = #{tenantId, jdbcType=BIGINT}
  AND revenue_closed_at IS NULL
  AND sales_delivery_detail_id IN

      #{detailId, jdbcType=BIGINT}
